#include "clang/StaticAnalyzer/Core/BugReporter/BugReporter.h"
#include "clang/StaticAnalyzer/Core/BugReporter/BugType.h"
#include "clang/StaticAnalyzer/Core/Checker.h"
#include "clang/StaticAnalyzer/Frontend/CheckerRegistry.h"
#include "llvm/Support/raw_ostream.h"
#include "clang/StaticAnalyzer/Checkers/utility.h"
#include "clang/AST/ASTContext.h"
#include "clang/AST/ParentMapContext.h"
#include "clang/AST/Stmt.h"
#include "clang/AST/Expr.h"
#include "clang/AST/Decl.h"
#include "llvm/ADT/StringMap.h"
#include "llvm/ADT/SmallVector.h"
#include "llvm/ADT/STLExtras.h"
#include <string>
#include <memory>
#include <functional>

using namespace clang;
using namespace ento;

namespace {

struct FreedTarget {
  std::string LabelName;
  const CallExpr *FreeCallCE;     // The free call statement (for diagnostics)
  const Expr *FreedExpr;          // The expression passed to free (arg0)
  std::string CalleeName;         // Name of free function (kfree, etc.)
};

class SAGenTestChecker : public Checker<check::ASTCodeBody> {
   mutable std::unique_ptr<BugType> BT;

   public:
      SAGenTestChecker() : BT(new BugType(this, "Suspicious cleanup free in early error path", "Memory Management")) {}

      void checkASTCodeBody(const Decl *D, AnalysisManager &Mgr, BugReporter &BR) const;

   private:

      // Helpers
      static bool isKnownFreeName(StringRef Name) {
        return Name.equals("kfree") || Name.equals("kvfree") || Name.equals("vfree");
      }

      // Identify a free-like sink from the callee declaration, falling back to
      // the callee expression when the direct callee is not resolved.
      static std::string getCallCalleeName(const CallExpr *CE) {
        if (!CE) return std::string();
        if (const FunctionDecl *FD = CE->getDirectCallee()) {
          if (const IdentifierInfo *II = FD->getIdentifier())
            return II->getName().str();
        }
        const Expr *CalleeE = CE->getCallee() ? CE->getCallee()->IgnoreParenImpCasts() : nullptr;
        if (const auto *DRE = dyn_cast_or_null<DeclRefExpr>(CalleeE)) {
          if (const auto *ND = dyn_cast<NamedDecl>(DRE->getDecl()))
            return ND->getNameAsString();
        }
        return std::string();
      }

      static const CallExpr *findFirstCallIn(const Stmt *S) {
        if (!S) return nullptr;
        if (const auto *CE = dyn_cast<CallExpr>(S))
          return CE;
        for (const Stmt *Child : S->children()) {
          if (!Child) continue;
          if (const CallExpr *Found = findFirstCallIn(Child))
            return Found;
        }
        return nullptr;
      }

      static void collectAllCallsIn(const Stmt *S, llvm::SmallVectorImpl<const CallExpr*> &Out) {
        if (!S) return;
        if (const auto *CE = dyn_cast<CallExpr>(S))
          Out.push_back(CE);
        for (const Stmt *Child : S->children()) {
          if (!Child) continue;
          collectAllCallsIn(Child, Out);
        }
      }

      static const GotoStmt *findFirstGotoIn(const Stmt *S) {
        if (!S) return nullptr;
        if (const auto *GS = dyn_cast<GotoStmt>(S))
          return GS;
        for (const Stmt *Child : S->children()) {
          if (!Child) continue;
          if (const GotoStmt *Found = findFirstGotoIn(Child))
            return Found;
        }
        return nullptr;
      }

      static const Expr *getFreedExprFromCall(const CallExpr *CE) {
        if (!CE || CE->getNumArgs() == 0) return nullptr;
        return CE->getArg(0)->IgnoreParenImpCasts();
      }

      static StringRef getLabelName(const LabelStmt *LS) {
        if (!LS) return StringRef();
        if (const LabelDecl *LD = LS->getDecl()) {
          if (const IdentifierInfo *II = LD->getIdentifier())
            return II->getName();
        }
        return StringRef();
      }

      static StringRef getLabelNameFromGoto(const GotoStmt *GS) {
        if (!GS) return StringRef();
        if (const LabelDecl *LD = GS->getLabel()) {
          if (const IdentifierInfo *II = LD->getIdentifier())
            return II->getName();
        }
        return StringRef();
      }

      static bool getEnclosingCompoundAndIndex(const Stmt *S, ASTContext &Ctx,
                                               const CompoundStmt *&OutCS, unsigned &OutIdx) {
        if (!S) return false;
        ParentMapContext &PMC = Ctx.getParentMapContext();
        const Stmt *Cur = S;
        // Limit the search depth to avoid pathological cases.
        for (int Depth = 0; Depth < 64 && Cur; ++Depth) {
          auto Parents = PMC.getParents(*Cur);
          if (Parents.empty())
            return false;
          const Stmt *Next = nullptr;
          for (const auto &P : Parents) {
            if (const auto *CS = P.get<CompoundStmt>()) {
              // Find the index of Cur in CS
              unsigned I = 0;
              for (const Stmt *Child : CS->body()) {
                if (Child == Cur) {
                  OutCS = CS;
                  OutIdx = I;
                  return true;
                }
                ++I;
              }
              // Even if parent is CS but Cur isn't direct child (shouldn't happen), continue.
            }
            if (const auto *PS = P.get<Stmt>()) {
              Next = PS;
              // Keep searching upwards until we hit a CompoundStmt that directly contains Cur.
            } else {
              // Parent is not a Stmt, likely a Decl - stop this branch.
            }
          }
          Cur = Next;
        }
        return false;
      }

      static const CallExpr *getCallFromAssignment(const Stmt *S) {
        if (!S) return nullptr;
        const auto *BO = dyn_cast<BinaryOperator>(S);
        if (!BO || !BO->isAssignmentOp())
          return nullptr;
        const Expr *RHS = BO->getRHS();
        return dyn_cast_or_null<CallExpr>(RHS ? RHS->IgnoreParenImpCasts() : nullptr);
      }

      static const CallExpr *getCallFromDeclInit(const Stmt *S) {
        const auto *DS = dyn_cast<DeclStmt>(S);
        if (!DS) return nullptr;
        for (const Decl *Di : DS->decls()) {
          if (const auto *VD = dyn_cast<VarDecl>(Di)) {
            if (const Expr *Init = VD->getInit()) {
              if (const auto *CE = dyn_cast<CallExpr>(Init->IgnoreParenImpCasts()))
                return CE;
            }
          }
        }
        return nullptr;
      }

      // Normalize the branch condition and extract the status variable whose
      // value guards this branch ("if (ret)", "if (!ret)", "if (ret != 0)").
      static const VarDecl *getGuardStatusVar(const IfStmt *IfS) {
        if (!IfS) return nullptr;
        const Expr *Cond = IfS->getCond();
        if (!Cond) return nullptr;
        Cond = Cond->IgnoreParenImpCasts();
        if (const auto *UO = dyn_cast<UnaryOperator>(Cond)) {
          if (UO->getOpcode() == UO_LNot)
            Cond = UO->getSubExpr()->IgnoreParenImpCasts();
        }
        if (const auto *BO = dyn_cast<BinaryOperator>(Cond)) {
          if (!BO->isComparisonOp())
            return nullptr;
          if (const auto *DRE = dyn_cast<DeclRefExpr>(BO->getLHS()->IgnoreParenImpCasts()))
            return dyn_cast<VarDecl>(DRE->getDecl());
          if (const auto *DRE = dyn_cast<DeclRefExpr>(BO->getRHS()->IgnoreParenImpCasts()))
            return dyn_cast<VarDecl>(DRE->getDecl());
          return nullptr;
        }
        if (const auto *DRE = dyn_cast<DeclRefExpr>(Cond))
          return dyn_cast<VarDecl>(DRE->getDecl());
        return nullptr;
      }

      // Return the call whose result was bound to StatusVar, searching a
      // bounded window of preceding siblings for "V = call(...)" or
      // "type V = call(...);" so unrelated statements between the binding and
      // the guard do not break the producer relation.
      static const CallExpr *findStatusBindingCall(const CompoundStmt *CS,
                                                   unsigned IfIdx,
                                                   const VarDecl *StatusVar) {
        if (!CS || !StatusVar) return nullptr;
        unsigned Start = IfIdx > 16 ? IfIdx - 16 : 0;
        for (unsigned I = IfIdx; I-- > Start;) {
          const Stmt *Cur = getStmtAtIndex(CS, I);
          if (!Cur) continue;

          if (const auto *BO = dyn_cast<BinaryOperator>(Cur)) {
            if (!BO->isAssignmentOp()) continue;
            const Expr *LHS = BO->getLHS() ? BO->getLHS()->IgnoreParenImpCasts() : nullptr;
            const auto *DRE = dyn_cast_or_null<DeclRefExpr>(LHS);
            if (!DRE || DRE->getDecl() != StatusVar) continue;
            if (const auto *CE = dyn_cast_or_null<CallExpr>(BO->getRHS() ? BO->getRHS()->IgnoreParenImpCasts() : nullptr))
              return CE;
            return findFirstCallIn(BO->getRHS());
          }

          if (const auto *DS = dyn_cast<DeclStmt>(Cur)) {
            for (const Decl *Di : DS->decls()) {
              if (const auto *VD = dyn_cast<VarDecl>(Di)) {
                if (VD != StatusVar || !VD->getInit()) continue;
                if (const auto *CE = dyn_cast<CallExpr>(VD->getInit()->IgnoreParenImpCasts()))
                  return CE;
                return findFirstCallIn(VD->getInit());
              }
            }
          }
        }
        return nullptr;
      }

      static const CallExpr *findCallBeforeIf(const IfStmt *IfS, ASTContext &Ctx) {
        if (!IfS) return nullptr;

        // Case 1: the failing call is the normalized branch condition
        // (if (call(...)), if (!call(...)), if (call(...) != 0)).
        const Expr *Cond = IfS->getCond() ? IfS->getCond()->IgnoreParenImpCasts() : nullptr;
        if (Cond) {
          if (const auto *UO = dyn_cast<UnaryOperator>(Cond)) {
            if (UO->getOpcode() == UO_LNot)
              Cond = UO->getSubExpr()->IgnoreParenImpCasts();
          }
          if (const auto *BO = dyn_cast<BinaryOperator>(Cond)) {
            if (BO->isComparisonOp()) {
              const Expr *L = BO->getLHS()->IgnoreParenImpCasts();
              const Expr *R = BO->getRHS()->IgnoreParenImpCasts();
              if (isa<CallExpr>(L))
                Cond = L;
              else if (isa<CallExpr>(R))
                Cond = R;
            }
          }
          if (const auto *CE = dyn_cast<CallExpr>(Cond))
            return CE;
        }

        const CompoundStmt *CS = nullptr;
        unsigned Idx = 0;
        if (!getEnclosingCompoundAndIndex(IfS, Ctx, CS, Idx) || !CS)
          return nullptr;

        // Case 2: the guard variable holds the result of the failing call.
        if (const VarDecl *StatusVar = getGuardStatusVar(IfS)) {
          if (const CallExpr *CE = findStatusBindingCall(CS, Idx, StatusVar))
            return CE;
        }

        // Case 3: nearest preceding sibling that directly yields a call.
        if (Idx == 0)
          return nullptr;

        const Stmt *Prev = getStmtAtIndex(CS, Idx - 1);
        if (!Prev) return nullptr;

        if (const CallExpr *CE = getCallFromAssignment(Prev))
          return CE;
        if (const CallExpr *CE = getCallFromDeclInit(Prev))
          return CE;

        // Also consider if the previous statement is directly a call.
        if (const auto *CE = dyn_cast<CallExpr>(Prev))
          return CE;

        // Or contains a call anywhere (less strict)
        return findFirstCallIn(Prev);
      }

      static void collectStructPtrArgs(const CallExpr *CE,
                                       llvm::SmallVectorImpl<const VarDecl*> &Out) {
        if (!CE) return;
        for (unsigned i = 0; i < CE->getNumArgs(); ++i) {
          const Expr *Arg = CE->getArg(i)->IgnoreParenImpCasts();
          const auto *DRE = dyn_cast<DeclRefExpr>(Arg);
          if (!DRE) continue;
          const auto *VD = dyn_cast<VarDecl>(DRE->getDecl());
          if (!VD) continue;
          QualType T = DRE->getType();
          if (const auto *PT = T->getAs<PointerType>()) {
            QualType Pointee = PT->getPointeeType();
            if (Pointee->getAs<RecordType>()) {
              Out.push_back(VD);
            }
          }
        }
      }

      static bool isMemberOfVar(const Expr *E, const VarDecl *V, std::string &FieldNameOut) {
        if (!E) return false;
        const auto *ME = dyn_cast<MemberExpr>(E->IgnoreParenImpCasts());
        if (!ME) return false;
        const Expr *Base = ME->getBase();
        if (!Base) return false;
        const auto *DRE = dyn_cast<DeclRefExpr>(Base->IgnoreParenImpCasts());
        if (!DRE) return false;
        const auto *BVD = dyn_cast<VarDecl>(DRE->getDecl());
        if (!BVD || BVD != V) return false;
        if (const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl())) {
          FieldNameOut = FD->getNameAsString();
          return true;
        }
        if (const auto *ND = dyn_cast<NamedDecl>(ME->getMemberDecl())) {
          FieldNameOut = ND->getNameAsString();
          return true;
        }
        return false;
      }

      static bool stmtContainsAssignmentToMember(const Stmt *S,
                                                 const VarDecl *Base,
                                                 StringRef Field) {
        if (!S) return false;

        // Check if S is an assignment to the target member
        if (const auto *BO = dyn_cast<BinaryOperator>(S)) {
          if (BO->isAssignmentOp()) {
            const Expr *LHS = BO->getLHS();
            const auto *ME = dyn_cast<MemberExpr>(LHS ? LHS->IgnoreParenImpCasts() : nullptr);
            if (ME) {
              const Expr *BaseE = ME->getBase();
              const auto *DRE = dyn_cast<DeclRefExpr>(BaseE ? BaseE->IgnoreParenImpCasts() : nullptr);
              const auto *BVD = DRE ? dyn_cast<VarDecl>(DRE->getDecl()) : nullptr;
              if (BVD == Base) {
                std::string Name;
                if (const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl()))
                  Name = FD->getNameAsString();
                else if (const auto *ND = dyn_cast<NamedDecl>(ME->getMemberDecl()))
                  Name = ND->getNameAsString();
                if (!Name.empty() && Field.equals(Name))
                  return true;
              }
            }
          }
        }

        // Recurse into children
        for (const Stmt *Child : S->children()) {
          if (!Child) continue;
          if (stmtContainsAssignmentToMember(Child, Base, Field))
            return true;
        }
        return false;
      }

      // Helper to get the number of statements in a CompoundStmt in a version-agnostic way.
      static unsigned getCompoundBodySize(const CompoundStmt *CS) {
        unsigned N = 0;
        for (const Stmt *Child : CS->body()) {
          (void)Child;
          ++N;
        }
        return N;
      }

      // Helper to get the statement at a given index in a CompoundStmt.
      static const Stmt *getStmtAtIndex(const CompoundStmt *CS, unsigned Index) {
        unsigned I = 0;
        for (const Stmt *Child : CS->body()) {
          if (I == Index)
            return Child;
          ++I;
        }
        return nullptr;
      }

      // Collect the free-like calls of one cleanup-region statement and
      // record them under the cleanup label that owns the statement.
      static void addFreeTargetsInStmt(const Stmt *S, StringRef LName,
                                       llvm::StringMap<llvm::SmallVector<FreedTarget, 4>> &OutMap) {
        if (!S) return;
        llvm::SmallVector<const CallExpr*, 8> Calls;
        collectAllCallsIn(S, Calls);
        for (const CallExpr *CE : Calls) {
          std::string CalleeName = getCallCalleeName(CE);
          if (!isKnownFreeName(CalleeName)) continue;

          const Expr *Arg0 = getFreedExprFromCall(CE);
          if (!Arg0) continue;

          FreedTarget FT;
          FT.LabelName = LName.str();
          FT.FreeCallCE = CE;
          FT.FreedExpr = Arg0;
          FT.CalleeName = CalleeName;
          OutMap[LName].push_back(FT);
        }
      }

      static void buildCleanupMap(const Stmt *Body, ASTContext &Ctx,
                                  llvm::StringMap<llvm::SmallVector<FreedTarget, 4>> &OutMap) {
        if (!Body) return;

        // Traverse the body to find all LabelStmt
        llvm::SmallVector<const LabelStmt*, 16> Labels;
        // Collect labels
        std::function<void(const Stmt*)> CollectLabels = [&](const Stmt *S){
          if (!S) return;
          if (const auto *LS = dyn_cast<LabelStmt>(S))
            Labels.push_back(LS);
          for (const Stmt *Child : S->children()) {
            if (Child) CollectLabels(Child);
          }
        };
        CollectLabels(Body);

        // For each label, scan forward in the enclosing compound to collect free-like calls
        for (const LabelStmt *LS : Labels) {
          StringRef LName = getLabelName(LS);
          if (LName.empty()) continue;

          const CompoundStmt *CS = nullptr;
          unsigned Idx = 0;
          if (!getEnclosingCompoundAndIndex(LS, Ctx, CS, Idx) || !CS)
            continue;

          // The first statement of the cleanup region is the LabelStmt's
          // own sub-statement ("label:\n free(x);"), not a following
          // sibling, so collect the label's subtree before scanning forward.
          addFreeTargetsInStmt(LS, LName, OutMap);

          // Scan forward from the statement just after the LabelStmt
          unsigned CSSize = getCompoundBodySize(CS);
          for (unsigned I = Idx + 1; I < CSSize; ++I) {
            const Stmt *Cur = getStmtAtIndex(CS, I);
            if (!Cur) continue;

            if (isa<LabelStmt>(Cur)) {
              // Another label signals end of this cleanup region
              break;
            }

            // Collect known free calls within this statement
            addFreeTargetsInStmt(Cur, LName, OutMap);

            // Stop at control-flow ending constructs, typical for cleanup regions
            if (isa<ReturnStmt>(Cur) || isa<GotoStmt>(Cur) || isa<BreakStmt>(Cur) || isa<ContinueStmt>(Cur))
              break;
          }
        }
      }

      static void collectIfStmts(const Stmt *Body, llvm::SmallVectorImpl<const IfStmt*> &Out) {
        if (!Body) return;
        if (const auto *IS = dyn_cast<IfStmt>(Body))
          Out.push_back(IS);
        for (const Stmt *Child : Body->children()) {
          if (!Child) continue;
          collectIfStmts(Child, Out);
        }
      }

      static bool sawPriorLocalAssignmentTo(const IfStmt *IfS, ASTContext &Ctx,
                                            const VarDecl *Base, StringRef Field) {
        if (!IfS || !Base) return false;
        const CompoundStmt *CS = nullptr;
        unsigned IfIdx = 0;
        if (!getEnclosingCompoundAndIndex(IfS, Ctx, CS, IfIdx) || !CS)
          return false;

        // Search in siblings before IfS
        for (unsigned I = 0; I < IfIdx; ++I) {
          const Stmt *Cur = getStmtAtIndex(CS, I);
          if (!Cur) continue;
          if (stmtContainsAssignmentToMember(Cur, Base, Field))
            return true;
        }
        return false;
      }

      // Aliasing ownership relation for the double-free mechanism: the
      // callee hands ownership of one of its locals to the caller's object
      // by storing it into "param.Field" and later frees that same local on
      // its own error path. After such a failure the object reachable from
      // the caller's "arg.Field" is already freed, so the caller's goto
      // cleanup free of "arg.Field" is a double free. The formal parameter
      // is bound to the caller's actual argument by position, and the store
      // must precede the free, so both sides denote one object in order.
      static bool calleeStoresFieldThenFreesLocal(const FunctionDecl *Def,
                                                  const ParmVarDecl *Param,
                                                  StringRef Field) {
        if (!Def || !Param || !Def->hasBody())
          return false;

        llvm::SmallVector<const VarDecl*, 4> StoredLocals;
        bool Freed = false;
        std::function<void(const Stmt*)> Walk = [&](const Stmt *S) {
          if (!S || Freed)
            return;

          // Ownership hand-off store: "Param.Field = local;"
          if (const auto *BO = dyn_cast<BinaryOperator>(S)) {
            if (BO->isAssignmentOp()) {
              const Expr *LHS = BO->getLHS() ? BO->getLHS()->IgnoreParenImpCasts() : nullptr;
              const Expr *RHS = BO->getRHS() ? BO->getRHS()->IgnoreParenImpCasts() : nullptr;
              const auto *ME = dyn_cast_or_null<MemberExpr>(LHS);
              const auto *RD = dyn_cast_or_null<DeclRefExpr>(RHS);
              if (ME && RD) {
                const Expr *Base = ME->getBase();
                const auto *BDRE =
                    dyn_cast_or_null<DeclRefExpr>(Base ? Base->IgnoreParenImpCasts() : nullptr);
                if (BDRE && BDRE->getDecl() == Param) {
                  std::string MF;
                  if (const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl()))
                    MF = FD->getNameAsString();
                  if (!MF.empty() && Field.equals(MF)) {
                    const auto *L = dyn_cast<VarDecl>(RD->getDecl());
                    if (L)
                      StoredLocals.push_back(L);
                  }
                }
              }
            }
          }

          // The handed-off local itself is freed: "free(local);"
          if (const auto *CE = dyn_cast<CallExpr>(S)) {
            if (CE->getNumArgs() > 0 && isKnownFreeName(getCallCalleeName(CE))) {
              const Expr *A0 = CE->getArg(0)->IgnoreParenImpCasts();
              const auto *ADRE = dyn_cast_or_null<DeclRefExpr>(A0);
              if (ADRE) {
                const auto *L = dyn_cast<VarDecl>(ADRE->getDecl());
                if (L && llvm::is_contained(StoredLocals, L)) {
                  Freed = true;
                  return;
                }
              }
            }
          }

          for (const Stmt *Child : S->children()) {
            if (Child)
              Walk(Child);
          }
        };
        Walk(Def->getBody());
        return Freed;
      }

      // Ownership relation for the double-free mechanism: the direct callee
      // of the failing call frees, on its own path, the same "param.Field"
      // object that the caller's goto cleanup region frees again. The callee's
      // formal parameter is mapped back to the caller's actual argument so
      // both sides denote one object. Abstains (returns false) when the
      // callee body is unavailable or no such freeing relation is proven,
      // which keeps cleanup paths whose failing call never freed the object
      // silent.
      static bool calleeFreesMemberOfCallerArg(const CallExpr *FailingCall,
                                               const VarDecl *CallerBase,
                                               StringRef Field) {
        if (!FailingCall || !CallerBase)
          return false;
        const FunctionDecl *Callee = FailingCall->getDirectCallee();
        if (!Callee)
          return false;
        const FunctionDecl *Def = Callee->getDefinition();
        if (!Def || !Def->hasBody())
          return false;

        llvm::SmallVector<const CallExpr*, 16> InnerCalls;
        collectAllCallsIn(Def->getBody(), InnerCalls);

        for (const CallExpr *Inner : InnerCalls) {
          if (!isKnownFreeName(getCallCalleeName(Inner)))
            continue;
          if (Inner->getNumArgs() == 0)
            continue;
          const Expr *Freed = Inner->getArg(0)->IgnoreParenImpCasts();
          const auto *ME = dyn_cast<MemberExpr>(Freed);
          if (!ME)
            continue;
          const Expr *BaseE = ME->getBase();
          const auto *BaseDRE = dyn_cast_or_null<DeclRefExpr>(
              BaseE ? BaseE->IgnoreParenImpCasts() : nullptr);
          if (!BaseDRE)
            continue;
          const auto *Param = dyn_cast<ParmVarDecl>(BaseDRE->getDecl());
          if (!Param)
            continue;
          // Map the callee's formal parameter back to the caller's argument.
          unsigned ParamIdx = Def->getNumParams();
          for (unsigned i = 0; i < Def->getNumParams(); ++i) {
            if (Def->getParamDecl(i) == Param) {
              ParamIdx = i;
              break;
            }
          }
          if (ParamIdx >= Def->getNumParams() ||
              ParamIdx >= FailingCall->getNumArgs())
            continue;
          const Expr *CallerArg =
              FailingCall->getArg(ParamIdx)->IgnoreParenImpCasts();
          const auto *ArgDRE = dyn_cast_or_null<DeclRefExpr>(CallerArg);
          if (!ArgDRE || ArgDRE->getDecl() != CallerBase)
            continue;
          std::string InnerField;
          if (const auto *FieldDeclD = dyn_cast<FieldDecl>(ME->getMemberDecl()))
            InnerField = FieldDeclD->getNameAsString();
          else if (const auto *ND = dyn_cast<NamedDecl>(ME->getMemberDecl()))
            InnerField = ND->getNameAsString();
          if (!InnerField.empty() && Field.equals(InnerField))
            return true;
        }

        // The callee can also hand ownership of a caller-visible object to
        // its own error path by storing one of its locals into "param.Field"
        // and then freeing that same local; the caller's cleanup free of
        // "arg.Field" is then a double free of that object.
        for (unsigned i = 0;
             i < Def->getNumParams() && i < FailingCall->getNumArgs(); ++i) {
          const Expr *A = FailingCall->getArg(i)->IgnoreParenImpCasts();
          const auto *ADRE = dyn_cast_or_null<DeclRefExpr>(A);
          if (!ADRE || ADRE->getDecl() != CallerBase)
            continue;
          if (calleeStoresFieldThenFreesLocal(Def, Def->getParamDecl(i), Field))
            return true;
        }
        return false;
      }
};

void SAGenTestChecker::checkASTCodeBody(const Decl *D, AnalysisManager &Mgr, BugReporter &BR) const {
  const auto *FD = dyn_cast<FunctionDecl>(D);
  if (!FD) return;
  const Stmt *Body = FD->getBody();
  if (!Body) return;

  ASTContext &Ctx = BR.getContext();

  // Step B: Build label -> cleanup free targets map
  llvm::StringMap<llvm::SmallVector<FreedTarget, 4>> CleanupMap;
  buildCleanupMap(Body, Ctx, CleanupMap);

  if (CleanupMap.empty())
    return;

  // Step C: Find IfStmts with early goto in then-branch and calls right before them
  llvm::SmallVector<const IfStmt*, 32> Ifs;
  collectIfStmts(Body, Ifs);

  AnalysisDeclContext *ADC = Mgr.getAnalysisDeclContext(D);

  for (const IfStmt *IfS : Ifs) {
    const Stmt *Then = IfS->getThen();
    if (!Then) continue;

    const GotoStmt *GS = findFirstGotoIn(Then);
    if (!GS) continue;

    StringRef TargetLabel = getLabelNameFromGoto(GS);
    if (TargetLabel.empty()) continue;

    auto It = CleanupMap.find(TargetLabel);
    if (It == CleanupMap.end()) continue;

    const CallExpr *FailingCall = findCallBeforeIf(IfS, Ctx);
    if (!FailingCall) continue;

    // Collect struct* arguments of the failing call
    llvm::SmallVector<const VarDecl*, 8> StructArgs;
    collectStructPtrArgs(FailingCall, StructArgs);
    if (StructArgs.empty()) continue;

    // Step D: For each free in the cleanup region, see if it's freeing a member of any struct arg
    for (const FreedTarget &FT : It->second) {
      const Expr *E = FT.FreedExpr;
      const auto *ME = dyn_cast<MemberExpr>(E ? E->IgnoreParenImpCasts() : nullptr);
      if (!ME) continue;

      const Expr *Base = ME->getBase();
      const auto *DRE = dyn_cast<DeclRefExpr>(Base ? Base->IgnoreParenImpCasts() : nullptr);
      if (!DRE) continue;

      const auto *BVD = dyn_cast<VarDecl>(DRE->getDecl());
      if (!BVD) continue;

      // Check if Base is among failing call's struct pointer args
      bool IsStructArg = llvm::is_contained(StructArgs, BVD);
      if (!IsStructArg) continue;

      // Extract member field name
      std::string FieldName;
      if (!isMemberOfVar(E, BVD, FieldName))
        continue;

      // Check whether this member was assigned earlier in this function before the IfS
      if (sawPriorLocalAssignmentTo(IfS, Ctx, BVD, FieldName))
        continue; // Locally initialized; skip warning

      // Double-free ownership relation: warn only when the failing call's own
      // callee already frees the same object (mapped through the shared
      // argument) that this goto cleanup region frees again. A cleanup path
      // whose failing call never freed the object stays silent.
      if (!calleeFreesMemberOfCallerArg(FailingCall, BVD, FieldName))
        continue;

      // Step E: Report
      PathDiagnosticLocation Loc = PathDiagnosticLocation::createBegin(FT.FreeCallCE, BR.getSourceManager(), ADC);
      auto R = std::make_unique<BasicBugReport>(
          *BT,
          "Suspicious free of 'param->field' in early error path; may double free or free uninitialized memory",
          Loc);
      R->addRange(FT.FreeCallCE->getSourceRange());
      BR.emitReport(std::move(R));
    }
  }
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
      "Detects goto-based early error cleanup that frees struct fields not initialized in the current function",
      "");
}

